// Set correct brightness AND trigger ramp if in ramp window
// Uses dynamic photoperiod schedule from global.payload.photo_*
// Output 1: slider value (immediate brightness)
// Output 2: dimmer #1 DIM command (dawn/dusk ramps, range 0-40)
// Output 3: dimmer #2 DIM command (midday ramps, range 40-60)
//
// Uses PARTIAL start so ramp finishes on time even after mid-ramp reboot.

var now = new Date();
var minutes = now.getHours() * 60 + now.getMinutes();

var dawnRamp = global.get('payload.photo_dawn_ramp');
var sunrise = global.get('payload.photo_sunrise');
var middayUp = global.get('payload.photo_midday_up');
var middayDown = global.get('payload.photo_midday_down');
var sunset = global.get('payload.photo_sunset');

if (dawnRamp === undefined || dawnRamp === null || sunrise === undefined || sunrise === null) {
    node.warn("Startup brightness: photoperiod not computed yet, skipping");
    return [null, null, null];
}

// Ramp durations are always 30 min
var dawnEnd = sunrise;                // dawn ramp complete = 40%
var middayUpEnd = middayUp + 30;      // midday up complete = 60%
var middayDownEnd = middayDown + 30;  // midday down complete = 40%
var duskEnd = sunset + 30;            // dusk ramp complete = 0%

var brightness = 0;
var dimmer1Msg = null;
var dimmer2Msg = null;

if (minutes >= dawnRamp && minutes < dawnEnd) {
    // Dawn ramp 0→40 (dimmer #1, t: 0→1)
    var elapsed = (minutes - dawnRamp) / 30;
    brightness = Math.round(elapsed * 40);
    dimmer1Msg = {payload: {command: "DIM", target: 1.0, start: elapsed}};
} else if (minutes >= dawnEnd && minutes < middayUp) {
    // Stable 40
    brightness = 40;
} else if (minutes >= middayUp && minutes < middayUpEnd) {
    // Midday ramp 40→60 (dimmer #2, t: 0→1)
    var elapsed = (minutes - middayUp) / 30;
    brightness = 40 + Math.round(elapsed * 20);
    dimmer2Msg = {payload: {command: "DIM", target: 1.0, start: elapsed}};
} else if (minutes >= middayUpEnd && minutes < middayDown) {
    // Stable 60
    brightness = 60;
} else if (minutes >= middayDown && minutes < middayDownEnd) {
    // Midday ramp 60→40 (dimmer #2, t: 1→0)
    var elapsed = (minutes - middayDown) / 30;
    brightness = 60 - Math.round(elapsed * 20);
    dimmer2Msg = {payload: {command: "DIM", target: 0.0, start: 1.0 - elapsed}};
} else if (minutes >= middayDownEnd && minutes < sunset) {
    // Stable 40
    brightness = 40;
} else if (minutes >= sunset && minutes < duskEnd) {
    // Dusk ramp 40→0 (dimmer #1, t: 1→0)
    var elapsed = (minutes - sunset) / 30;
    brightness = 40 - Math.round(elapsed * 40);
    dimmer1Msg = {payload: {command: "DIM", target: 0.0, start: 1.0 - elapsed}};
}

node.warn("Startup brightness=" + brightness + " (time: " + now.toLocaleTimeString() + ", min=" + minutes + ")" +
    (dimmer1Msg ? " + dimmer#1 ramp (start=" + dimmer1Msg.payload.start.toFixed(3) + ")" : "") +
    (dimmer2Msg ? " + dimmer#2 ramp (start=" + dimmer2Msg.payload.start.toFixed(3) + ")" : ""));

var sliderMsg = {payload: brightness};
return [sliderMsg, dimmer1Msg, dimmer2Msg];

