// PID Controller for Humidity/Temperature-Based Fan Control (Roraima Terrarium)
//
// THREE REGIMES:
//   Normal (T < 24°C): PID on humidity error (H-PID)
//   Warm (T 24-25°C, freezer OFF): PID on temperature error (T-PID)
//   Hot (T >= 25°C, freezer ON): PID on humidity error (H-PID)
//
// Error convention (humidity mode):
//   humidityDiff = target - current  (from Humidity tab)
//   error = -humidityDiff = current - target
//   Positive error (too humid) → increase fan speed
//
// GAIN SCHEDULING: Kp and Kd scale down near target to prevent oscillation.

const manualMode = flow.get('manual_fan_mode');
if (manualMode !== 'auto' && manualMode !== undefined) {
    node.status({ fill: "yellow", shape: "ring", text: "Manual mode" });
    return null;
}

const humidityDiff = global.get('payload.difference_humi');
if (humidityDiff === undefined || humidityDiff === null) {
    node.status({ fill: "red", shape: "dot", text: "No humidity data" });
    return null;
}

// PID tuning - adjustable via UI text input (Kp,Ki,Kd)
const tuning = flow.get('pid_tuning') || { Kp: 50, Ki: 0.5, Kd: 10 };

// PID state
let pid = flow.get('pid_values') || {
    integral: 0,
    lastError: 0,
    lastTime: Date.now(),
    filteredDeriv: 0
};

const now = Date.now();
const dt = (now - pid.lastTime) / 1000;

// Guard: skip if dt is zero or unreasonably large (restart/gap)
if (dt <= 0 || dt > 120) {
    pid.lastTime = now;
    flow.set('pid_values', pid);
    node.status({ fill: "grey", shape: "ring", text: "Waiting for next cycle" });
    return null;
}

// --- MODE SELECTION ---
const currentTemp = global.get('payload.current_temp');
const freezerStatus = global.get('payload.freezer_status');
const TEMP_PID_THRESHOLD = 24.0;
const TEMP_ERROR_SCALE = 5;  // Maps 0-1°C temp error to 0-5 PID-equivalent units

let controlMode;
if (currentTemp !== null && currentTemp !== undefined &&
    currentTemp >= TEMP_PID_THRESHOLD && !freezerStatus) {
    controlMode = 'temperature';
} else {
    controlMode = 'humidity';
}

// Reset PID state on mode transition to prevent integral bumps
const lastMode = flow.get('pid_control_mode');
if (lastMode && lastMode !== controlMode) {
    pid.integral = 0;
    pid.lastError = 0;
    pid.filteredDeriv = 0;
}
flow.set('pid_control_mode', controlMode);
global.set('payload.pid_control_mode', controlMode);

// Calculate error based on mode
let error;
if (controlMode === 'temperature') {
    error = (currentTemp - TEMP_PID_THRESHOLD) * TEMP_ERROR_SCALE;
} else {
    error = -humidityDiff;
}
const absError = Math.abs(error);

// === GAIN SCHEDULING ===
const NEAR_THRESH = 1.5;
const FAR_THRESH = 4.0;
const MIN_GAIN = 0.15;
const gainFactor = Math.min(1.0, Math.max(MIN_GAIN,
    MIN_GAIN + (1.0 - MIN_GAIN) * (absError - NEAR_THRESH) / (FAR_THRESH - NEAR_THRESH)));

// === PROPORTIONAL (gain-scheduled) ===
const P = tuning.Kp * gainFactor * error;

// === INTEGRAL with anti-windup ===
pid.integral += error * dt;
const I_MAX = 120 / Math.max(tuning.Ki, 0.001);
pid.integral = Math.max(-I_MAX, Math.min(I_MAX, pid.integral));

// Decay integral when error is small
if (absError < 2.0) {
    pid.integral *= (1 - 0.05 * dt);
}
const I = tuning.Ki * pid.integral;

// === DERIVATIVE with exponential low-pass filter (gain-scheduled) ===
const rawDeriv = (error - pid.lastError) / dt;
const alpha = 0.12;
pid.filteredDeriv = alpha * rawDeriv + (1 - alpha) * (pid.filteredDeriv || 0);
const D = tuning.Kd * gainFactor * pid.filteredDeriv;

// === TOTAL PID OUTPUT ===
const pidOutput = P + I + D;

// Map to fan speed
const BASE_SPEED = 50;
let fanSpeed = BASE_SPEED + pidOutput;

// Clamp to valid PWM range
const MIN_SPEED = 40;
const now_d = new Date();
const hours = now_d.getHours();
const mins = hours * 60 + now_d.getMinutes();
// Morning A/B experiment removed 2026-05-03 — gave it up after small/no observed effect
// MAX_SPEED is now uniform 255 (PID + floor/cap control without the A/B override)
let MAX_SPEED = 255;

// Morning A/B removed 2026-05-03 — keep payload.morning_experiment writing 0 for Data Logger backward-compat
global.set('payload.morning_experiment', 0);
fanSpeed = Math.max(MIN_SPEED, Math.min(MAX_SPEED, Math.round(fanSpeed)));

// Smooth transitions: limit rate of change
const lastSpeed = flow.get('last_fan_speed');
if (lastSpeed !== undefined && lastSpeed !== null) {
    const maxChange = Math.min(20, Math.max(8, absError * 2));
    const delta = fanSpeed - lastSpeed;
    if (Math.abs(delta) > maxChange) {
        fanSpeed = Math.round(lastSpeed + Math.sign(delta) * maxChange);
    }
}

// Store state
flow.set('last_fan_speed', fanSpeed);
global.set('payload.fan_speed', fanSpeed);
pid.lastError = error;
pid.lastTime = now;
flow.set('pid_values', pid);

// Node status display
const pct = Math.round((fanSpeed / 255) * 100);
const color = absError < 2 ? "green" : absError < 5 ? "yellow" : "red";
const modeLabel = (controlMode === 'temperature' ? 'T-PID' : 'H-PID');
const errLabel = controlMode === 'temperature'
    ? "T:" + currentTemp.toFixed(1) + "°C"
    : "Δ" + humidityDiff.toFixed(1) + "%";
const dir = error > 0 ? "▲" : error < 0 ? "▼" : "●";
node.status({
    fill: color, shape: "dot",
    text: modeLabel + " " + dir + " " + errLabel + " → " + pct + "% [P:" + P.toFixed(0) + " I:" + I.toFixed(0) + " D:" + D.toFixed(0) + " g:" + gainFactor.toFixed(2) + "]"
});

const status = {
    humidity_diff: +humidityDiff.toFixed(1),
    error: +error.toFixed(2),
    P: +P.toFixed(1),
    I: +I.toFixed(1),
    D: +D.toFixed(1),
    output: +pidOutput.toFixed(1),
    fan_speed: fanSpeed,
    fan_percent: pct,
    integral_accum: +pid.integral.toFixed(1),
    gain_factor: +gainFactor.toFixed(2),
    control_mode: controlMode
};

const tuningStr = "Kp=" + tuning.Kp + "  Ki=" + tuning.Ki + "  Kd=" + tuning.Kd;
return [{ payload: fanSpeed, pid_status: status }, { payload: status }, { payload: tuningStr }];

// Night fan mode - runs from midnight to 06:30
// Fans OFF during this period.
//
