        message += `Alert: Current temperature is too low (${currentTemp}°C).\n`;
    }
    if (currentTemp > 25) {
        message += `Alert: Current temperature is too high (${currentTemp}°C).\n`;
    }
    if (currentHumi < 75 || currentHumi > 97.5) {
        message += `Alert: Current humidity is out of range (${currentHumi}%).\n`;
    }
    if (waterLevel < 10) {
        message += `Alert: Water level is too low (${waterLevel}%).\n`;
    }
    alert = true;
} else if (msg.topic === 'periodic') {
    message = `Current status: Humidity: ${currentHumi}%, Temperature: ${currentTemp}°C, ΔHumidity: ${diffHumi}%, ΔTemperature: ${diffTemp}°C, Water Level: ${waterLevel}%`;
}

if (message) {
    msg.payload = message;
    msg.alert = alert;
    msg.text = message;
    return msg;
} else {
    return null;
}

// Terrarium Data Logger - reads all sensor data from global context
var currentTemp = global.get('payload.current_temp');
var currentHumi = global.get('payload.current_humi');
var vpd = global.get('payload.vpd');
var targetTemp = global.get('payload.target_temp');
var targetHumi = global.get('payload.target_humi');
var diffTemp = global.get('payload.difference_temp');
var diffHumi = global.get('payload.difference_humi');
var fanSpeed = global.get('payload.fan_speed');
var freezerStatus = global.get('payload.freezer_status');
var misterStatus = global.get('payload.mister_status');
var lightStatus = global.get('payload.light_status');
var waterLevel = global.get('payload.water_level');
var nightTestMode = global.get('payload.night_test_mode');
var wbtShutdown = global.get('payload.wbt_shutdown_active');
var pidControlMode = global.get('payload.pid_control_mode');
var morningExperiment = global.get('payload.morning_experiment');

// Arduino GPIO health: check heartbeat from analog pin read
var lastAlive = global.get('payload.arduino_gpio_alive') || 0;
var now = Date.now();
var arduinoStatus = (now - lastAlive < 300000) ? 1 : 0;  // 5 min grace

// Build output array - one msg per output, null if data unavailable
var outputs = [];
var values = [currentTemp, currentHumi, vpd, targetTemp, targetHumi, diffTemp, diffHumi, fanSpeed, freezerStatus, misterStatus, lightStatus, waterLevel, nightTestMode, arduinoStatus, wbtShutdown, pidControlMode, morningExperiment];

for (var i = 0; i < values.length; i++) {
    var v = values[i];
    if (v === undefined || v === null) {
        outputs.push(null);
    } else {
        if (typeof v === 'boolean') {
            v = v ? 1 : 0;
        }
        // Map string pid_control_mode to number
        if (i === 15 && typeof v === 'string') {
            v = (v === 'temperature') ? 1 : 0;
        }
        outputs.push({payload: v});
    }
}

var active = values.filter(v => v !== undefined && v !== null).length;
node.status({fill: active >= 10 ? "green" : "yellow", shape: "dot", text: active + "/17 metrics | Arduino: " + (arduinoStatus ? "OK" : "DEAD")});

return outputs;

// Parse DietPi InfluxDB response
try {
    const series = msg.payload.results[0].series[0];
    const vals = series.values[0];
    // columns: time, last_t_out, last_rh_out
    const t_out = vals[1];
    const rh_out = vals[2];

    if (t_out === null || rh_out === null) {
        node.status({fill:"red",shape:"ring",text:"null data"});
        return null;
    }

    // Store in global context for other nodes
    global.set('payload.room_temperature', t_out);
    global.set('payload.room_humidity', rh_out);

    node.status({fill:"green",shape:"dot",
        text: t_out.toFixed(1) + "°C " + rh_out.toFixed(1) + "%"});

    return [
        {payload: t_out},
        {payload: rh_out}
    ];
} catch(e) {
    node.status({fill:"red",shape:"dot",text: e.message});
    return null;
}

// Rate-limited heartbeat: update global timestamp every 10s
// Arduino sends H,<value> every 2s via serial
var lastUpdate = context.get('lastUpdate') || 0;
var now = Date.now();
if (now - lastUpdate > 10000) {
    global.set('payload.arduino_gpio_alive', now);
    context.set('lastUpdate', now);
    node.status({fill: 'green', shape: 'dot', text: 'alive ' + new Date().toLocaleTimeString()});
}
return null;

// Parse Arduino serial messages
// Output 0: Heartbeat (H,<value>) -> Arduino Heartbeat function
// Output 1: Left door (D22,<0|1>) -> left door LED + door controller
// Output 2: Right door (D24,<0|1>) -> right door LED + door controller
// Output 3: Resend signal (on READY) -> triggers fan/dimmer resend
// Output 4: RPM data (R,<circ>,<freeze>,<outlet>,<impeller>)
var line = msg.payload.toString().trim();
if (!line) return [null, null, null, null, null];

if (line.startsWith("H,")) {
    var val = parseInt(line.substring(2));
    if (!isNaN(val)) {
        return [{payload: val}, null, null, null, null];
    }
} else if (line.startsWith("R,")) {
    var parts = line.substring(2).split(",");
    if (parts.length === 4) {
        var rpms = {
            circulation: parseInt(parts[0]),
            freezer: parseInt(parts[1]),
            outlet: parseInt(parts[2]),
            impeller: parseInt(parts[3])
        };
        node.status({fill: "cyan", shape: "dot", text: "RPM " + parts.join("/") + " " + new Date().toLocaleTimeString()});
        return [null, null, null, null, {payload: rpms}];
    }
} else if (line.startsWith("D22,")) {
    var val = parseInt(line.substring(4));
    if (!isNaN(val)) {
        return [null, {payload: val, topic: "door_left"}, null, null, null];
    }
} else if (line.startsWith("D24,")) {
    var val = parseInt(line.substring(4));
    if (!isNaN(val)) {
        return [null, null, {payload: val, topic: "door_right"}, null, null];
    }
} else if (line === "READY") {
    node.status({fill: "green", shape: "dot", text: "Arduino READY " + new Date().toLocaleTimeString()});
    node.warn("Arduino sent READY \u2014 resending all PWM values");
    return [null, null, null, {payload: "resend"}, null];
} else if (line.startsWith("OK,")) {
    node.status({fill: "green", shape: "dot", text: line + " " + new Date().toLocaleTimeString()});
} else if (line.startsWith("S,")) {
    node.status({fill: "blue", shape: "ring", text: line});
    node.warn("Arduino status: " + line);
} else if (line.startsWith("ERR,")) {
    node.status({fill: "red", shape: "ring", text: line});
    node.warn("Arduino error: " + line);
}
return [null, null, null, null, null];

// On Arduino READY, resend all current PWM values
// Respects door safety, WBT shutdown, mister interlock, AND manual override
// (manual override added 2026-05-06).

var manualMode = global.get("payload.manual_fan_mode");
var manualSpeed = global.get("payload.manual_fan_speed");
if (manualMode === 'manual' && manualSpeed !== null && manualSpeed !== undefined) {
    var lightPWM_m = global.get("payload.last_dimmer_pwm") || 0;
    msg.payload = "P12," + manualSpeed + "\nP44," + manualSpeed + "\nP45," + manualSpeed + "\nP46," + manualSpeed + "\nP8," + lightPWM_m + "\n";
    node.warn("Resending MANUAL override: all fans=" + manualSpeed);
    return msg;
}

var doorSafety = global.get("payload.door_safety_active");


if (doorSafety) {
    var cmds = "P12,0\nP45,0\nP44,0\nP46,0\nP8,102\n";
    node.warn("Resending SAFE PWM (doors open): fans off, light=60% (PWM 102)");
    msg.payload = cmds;
    return msg;
}

var fan_speed = global.get("payload.fan_speed");

var now = new Date();
var hours = now.getHours();
var minutes = now.getMinutes();
var timeMinutes = hours * 60 + minutes;
// Fan schedule: 05:00-00:00 active, 00:00-05:00 off
var isFanTime = (timeMinutes >= 300);

var outletVal = 0;
var impellerVal = 0;
var freezerVal = 140;  // baseline 140 since 2026-05-06 — quiet idle after pin-44 fan repair

if (isFanTime && fan_speed !== null && fan_speed !== undefined) {
    outletVal = fan_speed;
    impellerVal = fan_speed;
}

var freezerStatus = global.get("payload.freezer_status");
if (freezerStatus) {
    freezerVal = 255;
}

// WBT shutdown gate: zero outlet + impeller when terrarium <= room WBT
var wbtShutdown = global.get("payload.wbt_shutdown_active");
if (wbtShutdown) {
    outletVal = 0;
    impellerVal = 0;
}

// Mister interlock: all fans off during misting
var misterStatus = global.get("payload.mister_status");
if (misterStatus) {
    outletVal = 0;
    impellerVal = 0;
    freezerVal = 0;
}

// Circulation tracks freezer at all times (per design)
// Also zero during misting
var circulationVal = freezerVal;
if (misterStatus) {
    circulationVal = 0;
}

var lightPWM = global.get("payload.last_dimmer_pwm") || 0;

var cmds = "P12," + circulationVal + "\n" +
           "P45," + outletVal + "\n" +
           "P44," + freezerVal + "\n" +
           "P46," + impellerVal + "\n" +
           "P8," + lightPWM + "\n";

node.warn("Resending PWM: P12=" + circulationVal + " P45=" + outletVal + " P44=" + freezerVal + " P46=" + impellerVal + " P8=" + lightPWM);

msg.payload = cmds;
return msg;

// Track both doors, compute OR, fire on transitions only
// 3-second debounce: door must stay open for 3s before safety fires
// Spurious open/close within 3s is suppressed entirely
// Set global door_safety_enabled to false to disable
var enabled = global.get("payload.door_safety_enabled");
if (enabled === false) { return [null, null]; }

var left = flow.get("door_left_state") || 0;
var right = flow.get("door_right_state") || 0;
var wasOpen = (left || right) ? true : false;

if (msg.topic === "door_left") {
    left = msg.payload;
    flow.set("door_left_state", left);
} else if (msg.topic === "door_right") {
    right = msg.payload;
    flow.set("door_right_state", right);
} else {
    return [null, null];
}

var isOpen = (left || right) ? true : false;

// Update global context
global.set("payload.doors_status", isOpen ? 1 : 0);
global.set("payload.doors_open", isOpen);

var ts = new Date().toLocaleTimeString();
node.status({
    fill: isOpen ? "red" : "green",
    shape: "dot",
    text: (isOpen ? "OPEN" : "CLOSED") + " L=" + left + " R=" + right + " " + ts
});

// --- Debounced transitions ---
if (isOpen && !wasOpen) {
    // Door just opened — start debounce timer
    var timer = context.get("debounce_timer");
    if (timer) clearTimeout(timer);

    var newTimer = setTimeout(function() {
        context.set("debounce_timer", null);
        context.set("safety_fired", true);
        node.warn("Door opened (confirmed 3s): L=" + left + " R=" + right);
        node.send([{payload: "door_opened", topic: "door_opened"}, null]);
    }, 3000);
    context.set("debounce_timer", newTimer);
    return [null, null];
}

if (!isOpen && wasOpen) {
    // Door just closed
    var timer = context.get("debounce_timer");
    if (timer) {
        // Closed within 3s — spurious event, cancel everything
        clearTimeout(timer);
        context.set("debounce_timer", null);
        node.status({fill: "yellow", shape: "ring", text: "spurious " + ts});
        return [null, null];
    }
    // Only fire all_closed if we actually fired door_opened
    if (context.get("safety_fired")) {
        context.set("safety_fired", false);
        node.warn("All doors closed");
        return [null, {payload: "all_closed", topic: "all_closed"}];
    }
    return [null, null];
}

return [null, null];

// Door Safety Controller
// Output 0: serial commands -> serial_out
// Output 1: freezer Tapo -> link -> freezer gate
// Output 2: mister Tapo -> link -> mister gate
// Output 3: light Tapo -> link -> light gate
//
// Manual-fan-mode awareness (2026-05-06): when global.payload.manual_fan_mode === 'manual'
// the operator has explicitly chosen a fan state via the UI buttons — the open/close
// handlers leave fans alone in that case (only light + Tapo plugs follow door safety).

if (msg.topic === "door_opened") {
    global.set("payload.door_saved_light_state", global.get("payload.light_status") || 0);
    global.set("payload.door_saved_freezer_state", global.get("payload.freezer_status") || false);
    global.set("payload.door_safety_active", true);

    var manualMode = global.get("payload.manual_fan_mode");
    var inManual = (manualMode === 'manual');

    var serialMsg = inManual
        ? {payload: "P8,102\n"}                                  // light only; fans kept in manual
        : {payload: "P12,0\nP44,0\nP45,0\nP46,0\nP8,102\n"};     // normal door-safety stop
    var freezerOff = {payload: "off"};
    var misterOff  = {payload: "off"};
    var lightOn    = {payload: "on"};

    node.status({fill:'red',shape:'dot',text: (inManual ? 'SAFETY ON (manual fans kept) ' : 'SAFETY ON ') + new Date().toLocaleTimeString()});
    node.warn('Door safety: ' + (inManual ? 'fans LEFT in manual override' : 'fans OFF') + ', freezer OFF, mister OFF, light ON 60%');

    return [serialMsg, freezerOff, misterOff, lightOn];

} else if (msg.topic === "all_closed") {
    global.set("payload.door_safety_active", false);

    var manualMode = global.get("payload.manual_fan_mode");
    var inManual = (manualMode === 'manual');

    var lightPWM = global.get("payload.last_dimmer_pwm") || 0;

    if (inManual) {
        // Restore light + Tapo states; fans stay where the operator set them.
        var serialMsgM = {payload: "P8," + lightPWM + "\n"};
        var wasFreezerOnM = global.get("payload.door_saved_freezer_state");
        var freezerCmdM = wasFreezerOnM ? {payload: "on"} : null;
        var wasLightOnM = global.get("payload.door_saved_light_state");
        var lightCmdM = wasLightOnM ? null : {payload: "off"};
        node.status({fill:'green',shape:'dot',text:'SAFETY OFF (manual fans kept) ' + new Date().toLocaleTimeString()});
        node.warn('Door safety off: fans LEFT in manual mode, light/Tapo restored');
        return [serialMsgM, freezerCmdM, null, lightCmdM];
    }

    // ── Normal restore (auto mode) ─────────────────────────────────
    var now = new Date();
    var hours = now.getHours();
    var minutes = now.getMinutes();
    var timeMinutes = hours * 60 + minutes;
    var isFanTime = (timeMinutes >= 240);  // 04:00–00:00

    var freezerStatus = global.get("payload.freezer_status");
    var freezerVal = freezerStatus ? 255 : 140;  // baseline 140 since 2026-05-06 (post-repair quiet idle)
    var circulationVal = isFanTime ? freezerVal : 0;

    var outletVal = 0;
    var impellerVal = 0;
    if (isFanTime) {
        var fan_speed = global.get("payload.fan_speed");
        if (fan_speed !== null && fan_speed !== undefined) {
            outletVal = fan_speed;
            impellerVal = fan_speed;
        }
    }

    var misterActive = global.get("payload.mister_status");
    if (misterActive) {
        outletVal = 0;
        impellerVal = 0;
        freezerVal = 0;
        circulationVal = 0;
    }

    var serialMsg = {payload: "P12," + circulationVal + "\nP44," + freezerVal + "\nP45," + outletVal + "\nP46," + impellerVal + "\nP8," + lightPWM + "\n"};

    var wasFreezerOn = global.get("payload.door_saved_freezer_state");
    var freezerCmd = wasFreezerOn ? {payload: "on"} : null;

    var wasLightOn = global.get("payload.door_saved_light_state");
    var lightCmd = wasLightOn ? null : {payload: "off"};

    node.status({fill:'green',shape:'dot',text:'SAFETY OFF ' + new Date().toLocaleTimeString()});
    node.warn('Door safety off: fans restored P12=' + circulationVal + ' P44=' + freezerVal + ' P45=' + outletVal + ' P46=' + impellerVal + ' P8=' + lightPWM);

    return [serialMsg, freezerCmd, null, lightCmd];
}

return [null, null, null, null];

// Circulation fan serial writer (P12) with door safety gate + manual override bypass
// (updated 2026-05-06 — manual override bypasses door safety so Max-with-doors-open works)
var doorSafety = global.get("payload.door_safety_active");
var manualMode = flow.get("manual_fan_mode");  // same tab as Manual Fan Control
if (doorSafety && manualMode !== 'manual') return null;

var val = Math.round(Number(msg.payload));
if (isNaN(val)) return null;
if (val < 0) val = 0;
if (val > 255) val = 255;
msg.payload = "P12," + val + "\n";
return msg;

var roomTemp = global.get('payload.room_temperature');
var roomHumi = global.get('payload.room_humidity');

var tempMsg = null;
var humiMsg = null;
var wbtMsg = null;

if (roomTemp !== null && roomTemp !== undefined && !isNaN(roomTemp)) {
    tempMsg = {payload: Number(roomTemp), topic: 'room'};
}
if (roomHumi !== null && roomHumi !== undefined && !isNaN(roomHumi)) {
    humiMsg = {payload: Number(roomHumi), topic: 'room'};
}

// Wet-bulb temperature (Stull 2011 approximation, accurate to ~0.3C)
if (roomTemp !== null && roomTemp !== undefined && !isNaN(roomTemp) &&
    roomHumi !== null && roomHumi !== undefined && !isNaN(roomHumi)) {
    var T = Number(roomTemp);
    var RH = Number(roomHumi);
    var Tw = T * Math.atan(0.151977 * Math.pow(RH + 8.313659, 0.5))
           + Math.atan(T + RH)
           - Math.atan(RH - 1.676331)
           + 0.00391838 * Math.pow(RH, 1.5) * Math.atan(0.023101 * RH)
           - 4.686035;
    Tw = Math.round(Tw * 100) / 100;
    global.set('payload.room_wbt', Tw);
    wbtMsg = {payload: Tw, topic: 'wbt'};
}

return [tempMsg, humiMsg, wbtMsg];

// Restore mist counters on startup from flow context
var todayCount = flow.get('mist_count_today') || 0;
var ydayCount = flow.get('ycount') || 0;

node.warn("Restoring mist counts: today=" + todayCount + ", yesterday=" + ydayCount);

var todayMsg = {payload: todayCount, topic: "restore"};
var ydayMsg = {ycount: ydayCount, payload: ydayCount};
return [todayMsg, ydayMsg];

var watts = parseFloat(msg.payload);
if (isNaN(watts)) return null;
var uiMsg = {payload: Math.round(watts) + " W"};
var dbMsg = {payload: watts};
return [uiMsg, dbMsg];

// Lights-off Fan Gate (revised 2026-05-07, tag:wbt_gate_freezer_latch_2026_05_07)
//
// Stops outlet+impeller fans from "first freezer-on after lights-off" through 05:00.
// Between lights-off and the first freezer engagement the cabinet is still cooling
// on residual thermal mass — fans help that natural cooldown rather than fight it.
// Once the freezer kicks in, fans become counterproductive (mixing room-temp cabinet
// with the cold evaporator stream), so we hold them at 0 for the rest of the window.
// Latch resets when we exit the window (after 05:00 next morning).
//
// Signal flow: PID/Night Mode → this gate → outlet/impeller RBEs

var fanValue = msg.payload;
var lightOffMinutes = global.get('payload.photo_light_off');

// If photoperiod not computed yet, pass through
if (lightOffMinutes === undefined || lightOffMinutes === null) {
    node.status({fill:"yellow", shape:"ring", text:"No schedule | pass val=" + fanValue});
    global.set('payload.wbt_shutdown_active', 0);
    return msg;
}

var now = new Date();
var currentMinutes = now.getHours() * 60 + now.getMinutes();
var shutdownEnd = 5 * 60;  // 05:00

// Are we within the *potential* shutdown window?
var inWindow;
if (lightOffMinutes > shutdownEnd) {
    inWindow = (currentMinutes >= lightOffMinutes || currentMinutes < shutdownEnd);
} else {
    inWindow = (currentMinutes >= lightOffMinutes && currentMinutes < shutdownEnd);
}

if (!inWindow) {
    flow.set('freezer_engaged_postoff', false);  // reset latch outside window
    global.set('payload.wbt_shutdown_active', 0);
    node.status({fill:"green", shape:"dot", text:"Pass-through | val=" + fanValue});
    return msg;
}

// Inside window — check freezer engagement latch
var freezerOn = global.get('payload.freezer_status');
var latched = flow.get('freezer_engaged_postoff') || false;
if (freezerOn === true || freezerOn === 1) {
    latched = true;
    flow.set('freezer_engaged_postoff', true);
}

var fmtOff = String(Math.floor(lightOffMinutes/60)).padStart(2,'0') + ':' +
             String(lightOffMinutes%60).padStart(2,'0');

if (!latched) {
    // Lights off but freezer hasn't kicked in yet — let outlet+impeller assist the cooldown
    global.set('payload.wbt_shutdown_active', 0);
    node.status({fill:"yellow", shape:"dot",
        text:"Pre-freezer cooldown | off@" + fmtOff + " | val=" + fanValue});
    return msg;
}

// Freezer has engaged at least once — block fans for the rest of the window
global.set('payload.wbt_shutdown_active', 1);
node.status({fill:"blue", shape:"ring",
    text:"Shutdown (freezer-latched) | off@" + fmtOff + " | input=" + fanValue});
return {payload: 0};

var T = msg.payload;
if (T >= 24) T = 24.75;
msg.payload = T;
return msg;

// Calculate day length for Chinchina (4.98°N, Colombia)
// Clamp to 10-14h. Center on 13:15 Genoa time (current schedule midpoint).
// Derive all schedule times proportionally.

var now = new Date();
var start = new Date(now.getFullYear(), 0, 0);
var dayOfYear = Math.floor((now - start) / 86400000);
var lat = 4.9836;  // Chinchina, Caldas, Colombia
var latRad = lat * Math.PI / 180;
var declination = 23.45 * Math.sin((2 * Math.PI / 365) * (dayOfYear - 81));
var declRad = declination * Math.PI / 180;
var cosHA = Math.max(-1, Math.min(1, -Math.tan(latRad) * Math.tan(declRad)));
var daylightHours = 2 * Math.acos(cosHA) * 12 / Math.PI;

// Clamp 10-14h
daylightHours = Math.max(10, Math.min(14, daylightHours));
var halfDay = daylightHours * 60 / 2;

// Center on 13:15 Genoa time (795 min) = current schedule midpoint
var CENTER = 795;
var sunrise = Math.round(CENTER - halfDay);  // full brightness starts (40%)
var sunset  = Math.round(CENTER + halfDay);  // full brightness ends (40%)
var dawnRamp = sunrise - 30;                  // start ramp 30min before sunrise
var lightOn  = dawnRamp - 5;                  // Tapo on 5min before ramp
var duskRamp = sunset;                        // start dimming at sunset
var lightOff = sunset + 35;                   // Tapo off 5min after ramp ends
var middayUp   = sunrise + Math.round((sunset - sunrise) * 0.375);
var middayDown = sunrise + Math.round((sunset - sunrise) * 0.625);

global.set('payload.photo_daylight_hours', daylightHours);
global.set('payload.photo_light_on', lightOn);
global.set('payload.photo_light_off', lightOff);
global.set('payload.photo_sunrise', sunrise);
global.set('payload.photo_sunset', sunset);
global.set('payload.photo_dawn_ramp', dawnRamp);
global.set('payload.photo_dusk_ramp', duskRamp);
global.set('payload.photo_midday_up', middayUp);
global.set('payload.photo_midday_down', middayDown);

function fmtTime(m) {
    return String(Math.floor(m/60)).padStart(2,'0') + ':' + String(m%60).padStart(2,'0');
}

var info = "Day " + dayOfYear + " | " + daylightHours.toFixed(1) + "h | " +
    "On:" + fmtTime(lightOn) + " Dawn:" + fmtTime(dawnRamp) + "→" + fmtTime(sunrise) +
    " Mid:" + fmtTime(middayUp) + "/" + fmtTime(middayDown) +
    " Dusk:" + fmtTime(duskRamp) + "→" + fmtTime(duskRamp+30) + " Off:" + fmtTime(lightOff);
node.status({fill: "blue", shape: "dot", text: info});
node.warn("Photoperiod: " + info);

return msg;

// Unified Light Scheduler - replaces BigTimer + 4 time-injects
// Receives 1-minute ticks. Reads photo_* globals. Sends commands at computed times.
// Output 1: on/off string → light Tapo gate
// Output 2: dawn/dusk DIM commands → dimmer #1
// Output 3: midday up/down DIM commands → dimmer #2
//
// Catch-up logic: if a restart or Tapo failure caused a missed transition,
// retries every tick for up to 5 minutes before accepting the state.
// Ramp commands only fire on exact minute (dimmer expects single trigger).

var now = new Date();
var minutes = now.getHours() * 60 + now.getMinutes();

var lightOn = global.get('payload.photo_light_on');
var lightOff = global.get('payload.photo_light_off');
var dawnRamp = global.get('payload.photo_dawn_ramp');
var duskRamp = global.get('payload.photo_dusk_ramp');
var middayUp = global.get('payload.photo_midday_up');
var middayDown = global.get('payload.photo_midday_down');
var dayHours = global.get('payload.photo_daylight_hours');

if (lightOn === undefined || lightOn === null ||
    lightOff === undefined || lightOff === null) {
    node.status({fill: 'red', shape: 'ring', text: 'No schedule computed'});
    return [null, null, null];
}

var lightStatus = global.get('payload.light_status');
var shouldBeOn = (minutes >= lightOn && minutes < lightOff);
var MAX_RETRIES = 5;

var msg1 = null;
var msg2 = null;
var msg3 = null;
var catchUp = '';

// --- On/Off with catch-up retries ---
if (minutes === lightOn) {
    // Exact minute: send ON, reset retries
    flow.set('light_catchup_retries', 0);
    global.set('payload.light_status', 1);
    msg1 = {payload: 'on'};
} else if (minutes === lightOff) {
    // Exact minute: send OFF, reset retries
    flow.set('light_catchup_retries', 0);
    global.set('payload.light_status', 0);
    msg1 = {payload: 'off'};
} else if (shouldBeOn && (lightStatus === 0 || lightStatus === undefined || lightStatus === null)) {
    // Should be on but isn't — catch-up with retries
    var retries = flow.get('light_catchup_retries') || 0;
    if (retries < MAX_RETRIES) {
        flow.set('light_catchup_retries', retries + 1);
        msg1 = {payload: 'on'};
        catchUp = ' [catch-up ON ' + (retries + 1) + '/' + MAX_RETRIES + ']';
    } else {
        // Accept state after max retries
        global.set('payload.light_status', 1);
        flow.set('light_catchup_retries', 0);
        catchUp = ' [catch-up ON done]';
    }
} else if (!shouldBeOn && lightStatus === 1) {
    // Should be off but isn't — catch-up with retries
    var retries = flow.get('light_catchup_retries') || 0;
    if (retries < MAX_RETRIES) {
        flow.set('light_catchup_retries', retries + 1);
        msg1 = {payload: 'off'};
        catchUp = ' [catch-up OFF ' + (retries + 1) + '/' + MAX_RETRIES + ']';
    } else {
        global.set('payload.light_status', 0);
        flow.set('light_catchup_retries', 0);
        catchUp = ' [catch-up OFF done]';
    }
} else {
    // Steady state — clear retries
    flow.set('light_catchup_retries', 0);
}

// --- Ramp commands: exact minute only ---
if (minutes === dawnRamp) {
    msg2 = {payload: {command: 'DIM', target: 1.0, start: 0.0}};
} else if (minutes === duskRamp) {
    msg2 = {payload: {command: 'DIM', target: 0.0, start: 1.0}};
}

if (minutes === middayUp) {
    msg3 = {payload: {command: 'DIM', target: 1.0, start: 0.0}};
} else if (minutes === middayDown) {
    msg3 = {payload: {command: 'DIM', target: 0.0, start: 1.0}};
}

// --- Status display ---
function fmtTime(m) {
    return String(Math.floor(m/60)).padStart(2,'0') + ':' + String(m%60).padStart(2,'0');
}
var schedText = '☀ ' + (dayHours ? dayHours.toFixed(1) + 'h' : '?') +
    ' | On:' + fmtTime(lightOn) + ' Dawn:' + fmtTime(dawnRamp) +
    ' Mid:' + fmtTime(middayUp) + '/' + fmtTime(middayDown) +
    ' Dusk:' + fmtTime(duskRamp) + ' Off:' + fmtTime(lightOff) +
    ' [now:' + fmtTime(minutes) + ']' + catchUp;
node.status({fill: 'green', shape: 'dot', text: schedText});

return [msg1, msg2, msg3];

// Build historical weather curves from 14 days of OWM data
// Input: raw InfluxDB response from 8-statement query
//   0-3: temperature (chinchina, medellin, bogota, sonson)
//   4-7: humidity    (chinchina, medellin, bogota, sonson)

var data = msg.payload;
if (!data || !data.results) {
    node.warn("Historical curve: no data received");
    node.status({fill: "red", shape: "ring", text: "no data"});
    return null;
}

var SLOTS = 288; // 24h * 60min / 5min

// Initialize accumulators
var tempSum = new Array(SLOTS).fill(0);
var tempCount = new Array(SLOTS).fill(0);
var humiSum = new Array(SLOTS).fill(0);
var humiCount = new Array(SLOTS).fill(0);

var results = data.results;
var totalPoints = 0;

for (var r = 0; r < results.length; r++) {
    if (!results[r].series || !results[r].series[0]) continue;

    var series = results[r].series[0];
    var values = series.values;
    var isTemp = (r < 4);
    var accSum = isTemp ? tempSum : humiSum;
    var accCount = isTemp ? tempCount : humiCount;

    for (var i = 0; i < values.length; i++) {
        var val = values[i][1]; // [time, mean]
        if (val === null || val === undefined) continue;

        // Parse ISO timestamp to local time (Pi timezone = Europe/Rome)
        var date = new Date(values[i][0]);
        var minutesOfDay = date.getHours() * 60 + date.getMinutes();

        // Apply 15h shift: OWM recording at Genoa time T
        // maps to terrarium target at T + 15h
        var shiftedMinutes = (minutesOfDay + 15 * 60) % 1440;
        var slot = Math.floor(shiftedMinutes / 5);

        accSum[slot] += val;
        accCount[slot]++;
        totalPoints++;
    }
}

// Build final curves
var tempCurve = new Array(SLOTS).fill(null);
var humiCurve = new Array(SLOTS).fill(null);
var filledSlots = 0;

for (var s = 0; s < SLOTS; s++) {
    if (tempCount[s] > 0) {
        tempCurve[s] = Math.round(tempSum[s] / tempCount[s] * 10) / 10;
        filledSlots++;
    }
    if (humiCount[s] > 0) {
        humiCurve[s] = Math.round(humiSum[s] / humiCount[s] * 10) / 10;
    }
}

// Fill remaining null slots via circular linear interpolation
function interpolate(curve) {
    var firstValid = -1;
    for (var i = 0; i < SLOTS; i++) {
        if (curve[i] !== null) { firstValid = i; break; }
    }
    if (firstValid < 0) return;

    var lastValid = firstValid;
    for (var i = 1; i < SLOTS; i++) {
        var idx = (firstValid + i) % SLOTS;
        if (curve[idx] !== null) {
            var gap = (idx > lastValid) ? idx - lastValid : SLOTS - lastValid + idx;
            if (gap > 1) {
                for (var g = 1; g < gap; g++) {
                    var interpIdx = (lastValid + g) % SLOTS;
                    var frac = g / gap;
                    curve[interpIdx] = Math.round(
                        (curve[lastValid] * (1 - frac) + curve[idx] * frac) * 10
                    ) / 10;
                }
            }
            lastValid = idx;
        }
    }
}

interpolate(tempCurve);
interpolate(humiCurve);

// Circular moving average to smooth out 10-min sampling jitter
function smooth(curve, halfWin) {
    var n = curve.length;
    var out = new Array(n);
    for (var i = 0; i < n; i++) {
        var sum = 0;
        var count = 0;
        for (var d = -halfWin; d <= halfWin; d++) {
            var idx = (i + d + n) % n;
            if (curve[idx] !== null) { sum += curve[idx]; count++; }
        }
        out[i] = count > 0 ? Math.round(sum / count * 10) / 10 : curve[i];
    }
    return out;
}
tempCurve = smooth(smooth(tempCurve, 6), 6); // two-pass, 13-slot window
humiCurve = smooth(smooth(humiCurve, 6), 6);

// Store in globals
global.set("historical_temp_curve", tempCurve);
global.set("historical_humi_curve", humiCurve);

// Status
var coverage = Math.round(filledSlots / SLOTS * 100);
var now = new Date().toLocaleTimeString('it-IT', {hour: '2-digit', minute: '2-digit'});
node.status({fill: "green", shape: "dot",
    text: totalPoints + " pts, " + coverage + "% coverage, built " + now});

return null;

// Rolling mean with deploy-persistent buffer
var COUNT = 60;
var buffer = flow.get("smooth_temp_buf") || [];
buffer.push(msg.payload);
if (buffer.length > COUNT) buffer = buffer.slice(-COUNT);
flow.set("smooth_temp_buf", buffer);

var sum = 0;
for (var i = 0; i < buffer.length; i++) sum += buffer[i];
msg.payload = Math.round((sum / buffer.length) * 10) / 10;
return msg;

// Rolling mean with deploy-persistent buffer
var COUNT = 60;
var buffer = flow.get("smooth_humi_buf") || [];
buffer.push(msg.payload);
if (buffer.length > COUNT) buffer = buffer.slice(-COUNT);
flow.set("smooth_humi_buf", buffer);

var sum = 0;
for (var i = 0; i < buffer.length; i++) sum += buffer[i];
msg.payload = Math.round((sum / buffer.length) * 10) / 10;

// Emit RAW smoothed value. The 'Cap humidity 75-95%' node downstream
// on the control branch clamps before the global is set; the chart
// branch bypasses the cap and shows raw.
return msg;

var d = msg.payload;
msg.payload = [{ measurement: "darlingtonia", fields: { root: d.root, ambient: d.ambient, delta: d.delta, pump: d.pump ? 1 : 0, water: d.water ? 1 : 0, moist_raw: d.moist_raw, moist_pct: d.moist_pct, sleep_min: d.sleep_min, boot: d.boot } }];
return msg;

// LED Power Watchdog — model-based detection (updated 2026-05-05, tag:led_fault_watchdog_2026_05_05_model)
//
// Detects LED dim-signal failure: Mean Well drivers default to full output
// when PWM dim input floats. Trip when actual power exceeds expected+margin.
// Replaces the flat 140W threshold (which false-tripped under Curve C peak
// and door-open mode).
//
// Model:
//   leds_w(s)  = 2.8 * s          (4×100W rated × effective cap ~70% × s/100)
//   base       = doorSafety ? 18 : 32   (fans+freezer all forced off during door)
//   freezer_w  = (freezerOn && !doorSafety) ? 110 : 0
//   eff_slider = doorSafety ? 60                                  // door forces PWM 102
//              : (lightsOn  ? clamp(current_dimmer_slider, 0..100) : 0)
//   expected   = base + leds_w(eff_slider) + freezer_w
//   trip_w     = expected + MARGIN_W
//
// Trip if power > trip_w sustained SUSTAINED_SAMPLES samples.
// State machine unchanged: IDLE → LIGHTS_OFF (10min) → RECOVERY_TEST (60s) → LOCKED|IDLE.

const MARGIN_W              = 60;        // headroom over expected (W)
const SUSTAINED_SAMPLES     = 3;         // ~90s at Meross 30s cadence
const COOL_DOWN_MS          = 10 * 60 * 1000;
const RECOVERY_VERIFY_MS    = 60 * 1000;
const FAULT_FLAG_FILE       = '/tmp/led-fault.flag';
const LED_W_PER_SLIDER      = 2.8;       // 4 × 100W × ~60% cap ÷ 100
const BASE_NORMAL_W         = 32;
const BASE_DOOR_OPEN_W      = 18;
const FREEZER_W             = 170;
const DOOR_OPEN_SLIDER      = 60;        // forced by door-safety

// fs is injected via the function node's libs config
const TRANSIENT_FLAG_FILE   = '/tmp/led-transient-rate.flag';

function todayKey() { return new Date().toISOString().slice(0,10); }

function recordTransient(peakWatts, expectedWatts) {
    var today = todayKey();
    var trans = flow.get('led_transients');
    if (!trans || trans.date !== today) {
        trans = { date: today, count: 0 };
    }
    trans.count += 1;
    trans.last_event_ts = new Date().toISOString();
    trans.last_peak     = Math.round(peakWatts);
    trans.last_expected = Math.round(expectedWatts);
    flow.set('led_transients', trans);
    try { fs.writeFileSync(TRANSIENT_FLAG_FILE, JSON.stringify(trans) + '\n'); }
    catch(e) { node.warn('led-transient flag write failed: ' + e.message); }
    node.warn('LED transient #' + trans.count + ' today: ' + Math.round(peakWatts) +
              'W vs ' + Math.round(expectedWatts) + 'W expected');
}


function setStatus(c, t) { node.status({fill: c, shape: 'dot', text: t}); }
function writeFlag(obj) {
    try { fs.writeFileSync(FAULT_FLAG_FILE, JSON.stringify(obj) + '\n'); }
    catch(e) { node.warn('flag write fail: ' + e.message); }
}
function clearFlag() {
    try { if (fs.existsSync(FAULT_FLAG_FILE)) fs.unlinkSync(FAULT_FLAG_FILE); }
    catch(e) {}
}

function expectedCtx() {
    const lsRaw       = global.get('payload.light_status');
    const lightsOn    = (lsRaw === 1 || lsRaw === true);
    const doorSafety  = (global.get('payload.door_safety_active') === true);
    const freezerOn   = (global.get('payload.freezer_status') === 1 || global.get('payload.freezer_status') === true);
    const sliderRaw   = Number(global.get('payload.current_dimmer_slider'));
    const slider      = isNaN(sliderRaw) ? 0 : Math.max(0, Math.min(100, sliderRaw));

    const effSlider = doorSafety ? DOOR_OPEN_SLIDER : (lightsOn ? slider : 0);
    const base      = doorSafety ? BASE_DOOR_OPEN_W : BASE_NORMAL_W;
    const ledsW     = LED_W_PER_SLIDER * effSlider;
    const frzW      = (freezerOn && !doorSafety) ? FREEZER_W : 0;

    return {
        expected: base + ledsW + frzW,
        eff_slider: effSlider,
        doorSafety: doorSafety,
        freezerOn: freezerOn,
        lightsOn: lightsOn,
        slider_uninit: (sliderRaw === undefined || sliderRaw === null || isNaN(sliderRaw)),
    };
}

let state = flow.get('led_watchdog') || { phase: 'IDLE', suspect_count: 0, since: 0 };

// Manual reset path
if (msg.reset === true) {
    flow.set('led_watchdog', { phase: 'IDLE', suspect_count: 0, since: 0 });
    clearFlag();
    setStatus('green', 'Reset by user');
    var ls = global.get('payload.light_status');
    var wantOn = (ls === 1 || ls === true);
    node.warn('LED watchdog: manual reset received — Tapo ' + (wantOn ? 'ON (scheduler wants lights on)' : 'left OFF (scheduler wants lights off)'));
    return wantOn ? { payload: 'on' } : null;
}

const watts = msg.payload;
if (typeof watts !== 'number' || isNaN(watts)) return null;

const ctx = expectedCtx();

// Cold-start guard: if dimmer slider global hasn't been set yet, skip evaluation.
// The curve function sets it within ~8s of NR start; Meross polls every 30s,
// so this should only skip the very first sample after a fresh boot.
if (ctx.slider_uninit && state.phase === 'IDLE') {
    setStatus('grey', 'init — waiting for dimmer state (' + Math.round(watts) + 'W)');
    return null;
}

const trip_w = ctx.expected + MARGIN_W;
const now    = Date.now();
let tapoOut  = null;

if (state.phase === 'IDLE') {
    if (watts > trip_w) {
        state.suspect_count = (state.suspect_count || 0) + 1;
        state.last_spike_watts    = Math.max(state.last_spike_watts || 0, watts);
        state.last_spike_expected = ctx.expected;
        if (state.suspect_count >= SUSTAINED_SAMPLES) {
            state.phase = 'LIGHTS_OFF';
            state.since = now;
            state.fault_watts = watts;
            state.expected_at_fault = ctx.expected;
            tapoOut = { payload: 'off' };
            writeFlag({
                ts: new Date(now).toISOString(),
                phase: 'LIGHTS_OFF',
                watts: watts,
                expected: Math.round(ctx.expected),
                margin: MARGIN_W,
                slider: ctx.eff_slider,
                door_safety: ctx.doorSafety,
                freezer_on: ctx.freezerOn,
                msg: 'LED dim-signal anomaly: ' + Math.round(watts) + 'W vs expected ~' + Math.round(ctx.expected) + 'W (slider=' + ctx.eff_slider + (ctx.doorSafety ? ', door open' : '') + (ctx.freezerOn ? ', freezer on' : '') + '). Tapo OFF; will retry in 10 min.'
            });
            node.warn('LED FAULT: ' + Math.round(watts) + 'W vs ' + Math.round(ctx.expected) + 'W expected. Tapo OFF for 10min.');
            setStatus('red', 'FAULT — Tapo OFF (10min)');
        } else {
            setStatus('yellow', 'suspect ' + state.suspect_count + '/' + SUSTAINED_SAMPLES + ' (' + Math.round(watts) + 'W vs ' + Math.round(ctx.expected) + 'W)');
        }
    } else {
        if (state.suspect_count > 0 && state.last_spike_watts) {
            recordTransient(state.last_spike_watts, state.last_spike_expected || ctx.expected);
            state.last_spike_watts = 0;
        }
        state.suspect_count = 0;
        var trans_today = flow.get('led_transients');
        var n_today = (trans_today && trans_today.date === todayKey()) ? trans_today.count : 0;
        const tag = ctx.doorSafety ? ' DOOR' : (ctx.freezerOn ? ' FRZ' : '');
        var transient_tag = n_today > 0 ? ' [' + n_today + ' transients today]' : '';
        setStatus('green', 'OK ' + Math.round(watts) + 'W exp~' + Math.round(ctx.expected) + 'W' + tag + transient_tag);
    }
} else if (state.phase === 'LIGHTS_OFF') {
    const elapsed = now - state.since;
    if (elapsed >= COOL_DOWN_MS) {
        state.phase = 'RECOVERY_TEST';
        state.since = now;
        tapoOut = { payload: 'on' };
        node.warn('LED watchdog: 10min elapsed; Tapo ON for verify');
        setStatus('blue', 'Verifying after 10min off');
    } else {
        const remaining = Math.round((COOL_DOWN_MS - elapsed)/1000);
        setStatus('red', 'Locked off — retry in ' + remaining + 's');
    }
} else if (state.phase === 'RECOVERY_TEST') {
    const elapsed = now - state.since;
    if (elapsed >= RECOVERY_VERIFY_MS) {
        // Recompute expected — conditions may have changed during the 60s test
        const ctx2 = expectedCtx();
        const trip2 = ctx2.expected + MARGIN_W;
        if (watts > trip2) {
            state.phase = 'LOCKED';
            state.since = now;
            tapoOut = { payload: 'off' };
            writeFlag({
                ts: new Date(now).toISOString(),
                phase: 'LOCKED',
                watts: watts,
                expected: Math.round(ctx2.expected),
                margin: MARGIN_W,
                msg: 'LED fault persists after recovery: ' + Math.round(watts) + 'W vs expected ' + Math.round(ctx2.expected) + 'W. Lights LOCKED OFF — manual reset required.'
            });
            node.error('LED FAULT PERSISTS: ' + Math.round(watts) + 'W vs ' + Math.round(ctx2.expected) + 'W. LOCKED.');
            setStatus('red', 'LOCKED — manual reset required');
        } else {
            state.phase = 'IDLE';
            state.suspect_count = 0;
            clearFlag();
            node.warn('LED recovered — ' + Math.round(watts) + 'W is normal vs ' + Math.round(ctx2.expected) + 'W expected.');
            setStatus('green', 'Recovered');
        }
    } else {
        setStatus('blue', 'Verifying ' + Math.round(elapsed/1000) + 's/60s');
    }
} else if (state.phase === 'LOCKED') {
    setStatus('red', 'LOCKED — inject reset to clear');
}

flow.set('led_watchdog', state);
return tapoOut;

// Light Curve C — raised cosine with dawn/dusk linear ramps
// (updated 2026-05-05, tag:light_curve_C_2026_05_05_with_ramps)
//
// Restores the soft 30-min dawn/dusk transition that the original Curve C
// removed (it had a hard step from 0 → FLOOR at sunrise). Also emits the
// slider value on output 2 so the dashboard "Intensity of light" widget
// tracks live state instead of showing the stale Startup-brightness value.
//
// Phases (using photoperiod globals):
//   dawn_ramp ≤ t < sunrise:  linear ramp 0 → FLOOR over RAMP_MIN minutes
//   sunrise ≤ t ≤ sunset:     FLOOR + (PEAK-FLOOR)·cos(π·(t-noon)/L), clipped at FLOOR
//   sunset  < t ≤ sunset+RAMP_MIN: linear ramp FLOOR → 0
//   else:                     slider = 0 (lights off / outside curve)
//
// Outputs:
//   1: inverted PWM (0-255) → pin8_writer_001 (Arduino dim signal)
//   2: slider (0-100)       → ui_slider 'Intensity of light' (UI live)

const PEAK     = 70;
const FLOOR    = 35;
const RAMP_MIN = 30;   // dawn/dusk linear ramp duration (matches old dimmer #1)

const sunrise_min  = global.get('payload.photo_sunrise');
const sunset_min   = global.get('payload.photo_sunset');
let   dawn_ramp_min = global.get('payload.photo_dawn_ramp');

if (sunrise_min == null || sunset_min == null) {
    node.status({fill: 'gray', shape: 'ring', text: 'photo globals not set'});
    return [null, null];
}
if (dawn_ramp_min == null) dawn_ramp_min = sunrise_min - RAMP_MIN;
const dusk_end_min = sunset_min + RAMP_MIN;

const now = new Date();
const t_min = now.getHours() * 60 + now.getMinutes() + now.getSeconds()/60;
const solar_noon = (sunrise_min + sunset_min) / 2;
const day_length = sunset_min - sunrise_min;

let slider;
let phase_label;
if (t_min < dawn_ramp_min || t_min > dusk_end_min) {
    slider = 0;
    phase_label = 'off';
} else if (t_min < sunrise_min) {
    const r = (t_min - dawn_ramp_min) / RAMP_MIN;
    slider = FLOOR * Math.max(0, Math.min(1, r));
    phase_label = 'dawn';
} else if (t_min > sunset_min) {
    const r = (t_min - sunset_min) / RAMP_MIN;
    slider = FLOOR * Math.max(0, 1 - r);
    phase_label = 'dusk';
} else {
    const ph = Math.PI * (t_min - solar_noon) / day_length;
    const raw = FLOOR + (PEAK - FLOOR) * Math.cos(ph);
    slider = Math.max(FLOOR, raw);
    phase_label = 'cosine';
}

// Inverted PWM: slider 0 → PWM 255 (off), slider 100 → PWM 0 (full on)
const pwm = Math.round(2.55 * (100 - slider));

global.set('payload.current_dimmer_slider', slider);
global.set('payload.last_dimmer_pwm', pwm);

const hh = String(now.getHours()).padStart(2,'0');
const mm = String(now.getMinutes()).padStart(2,'0');
node.status({
    fill: slider == 0 ? 'gray' : (slider >= 60 ? 'orange' : 'yellow'),
    shape: 'dot',
    text: hh + ':' + mm + ' ' + phase_label + ' s=' + slider.toFixed(1) + ' PWM=' + pwm
});

return [
    { payload: pwm },
    { payload: Math.round(slider) }
];

// Manual Mode Watchdog — reverts manual fan override after 30 min.
// Added 2026-05-09 after a Pause button left fans at 0 PWM for 14h, risking the collection.
// Tag: manual_mode_30min_revert_2026_05_09
//
// Reads:
//   payload.manual_fan_mode      (set by Manual Fan Control on each button press)
//   payload.manual_fan_mode_set_at (epoch ms, stamped on each manual press, cleared on auto)
// Emits {payload:'auto'} to Manual Fan Control input when timeout fires.
// Survives NR restart — globals are persisted; if Pi reboots while in manual,
// the timestamp is preserved so the watchdog will still revert at the right time.

const MAX_AGE_MS = 30 * 60 * 1000;

const mode = global.get('payload.manual_fan_mode');
if (mode !== 'manual') {
    node.status({fill:'green',shape:'dot',text:'auto'});
    return null;
}

let setAt = global.get('payload.manual_fan_mode_set_at');
if (!setAt) {
    // Manual but no timestamp — stamp it now so watchdog will revert in 30 min.
    // This handles legacy state from before the timestamp field existed.
    setAt = Date.now();
    global.set('payload.manual_fan_mode_set_at', setAt);
    node.status({fill:'yellow',shape:'ring',text:'manual: stamped now'});
    return null;
}

const ageMs = Date.now() - setAt;
const remainSec = Math.max(0, Math.round((MAX_AGE_MS - ageMs) / 1000));

if (ageMs >= MAX_AGE_MS) {
    const speed = global.get('payload.manual_fan_speed');
    node.warn('Auto-reverting manual fan mode (was ' + speed + ' PWM for ' + Math.round(ageMs/60000) + ' min) → AUTO');
    node.status({fill:'orange',shape:'dot',text:'reverted to AUTO'});
    return {payload: 'auto'};
}

const mins = Math.floor(remainSec / 60);
const secs = remainSec % 60;
node.status({fill:'yellow',shape:'dot',text:'manual: ' + mins + 'm' + secs + 's left'});
return null;

// Probe DNS + outbound HTTP + LAN TCP; emit three msgs each minute.
// Output 0: connectivity_ok (1 or 0)
// Output 1: connectivity_dns_ms (number; null on fail -> output omitted)
// Output 2: connectivity_failures (0-3)
// Modules dns/http/net injected via this function's `libs` setup.
// LAN probe = TCP connect to Tapo freezer plug (192.168.1.196:80) — user's
// observation is that Tapos remain reachable during the daily network drop, so
// the failure mode we want to flag is when *that* breaks too (= wifi down).
// tag: connectivity_monitor_2026_05_14
const TIMEOUT_MS = 4000;

function probeDns() {
    return new Promise(resolve => {
        const t0 = Date.now();
        const timer = setTimeout(() => resolve({ok:false, err:'timeout', ms:null}), TIMEOUT_MS);
        dns.lookup('api.openweathermap.org', (err, addr) => {
            clearTimeout(timer);
            if (err) resolve({ok:false, err: String(err.code || err.message), ms:null});
            else resolve({ok:true, ms: Date.now() - t0, addr});
        });
    });
}

function probeHttp(host, port, path) {
    return new Promise(resolve => {
        let req;
        const timer = setTimeout(() => { try { req && req.destroy(); } catch(e){} resolve({ok:false, err:'timeout'}); }, TIMEOUT_MS);
        try {
            req = http.request({host, port, path, method:'HEAD', timeout: TIMEOUT_MS}, res => {
                clearTimeout(timer);
                res.on('data', ()=>{});
                res.on('end', ()=>resolve({ok:true, status: res.statusCode}));
            });
            req.on('error', err => { clearTimeout(timer); resolve({ok:false, err: String(err.code || err.message)}); });
            req.on('timeout', () => { clearTimeout(timer); try { req.destroy(); } catch(e){} resolve({ok:false, err:'timeout'}); });
            req.end();
        } catch (e) {
            clearTimeout(timer);
            resolve({ok:false, err: String(e.message || e)});
        }
    });
}

function probeTcp(host, port) {
    return new Promise(resolve => {
        let s;
        const timer = setTimeout(() => { try { s && s.destroy(); } catch(e){} resolve({ok:false, err:'timeout'}); }, TIMEOUT_MS);
        try {
            s = net.connect({host, port});
            s.setTimeout(TIMEOUT_MS);
            s.on('connect', () => { clearTimeout(timer); s.end(); resolve({ok:true}); });
            s.on('error', err => { clearTimeout(timer); resolve({ok:false, err: String(err.code || err.message)}); });
            s.on('timeout', () => { clearTimeout(timer); try { s.destroy(); } catch(e){} resolve({ok:false, err:'timeout'}); });
        } catch (e) {
            clearTimeout(timer);
            resolve({ok:false, err: String(e.message || e)});
        }
    });
}

(async () => {
    const [dnsRes, inetRes, lanRes] = await Promise.all([
        probeDns(),
        probeHttp('1.1.1.1', 80, '/'),
        probeTcp('192.168.1.196', 80)
    ]);

    const failures = (dnsRes.ok?0:1) + (inetRes.ok?0:1) + (lanRes.ok?0:1);
    const ok = failures === 0 ? 1 : 0;

    const parts = [];
    parts.push('DNS:' + (dnsRes.ok ? dnsRes.ms+'ms' : dnsRes.err));
    parts.push('NET:' + (inetRes.ok ? 'ok' : inetRes.err));
    parts.push('LAN:' + (lanRes.ok ? 'ok' : lanRes.err));
    node.status({
        fill: ok ? 'green' : (failures===3 ? 'red' : 'yellow'),
        shape: 'dot',
        text: parts.join(' ') + ' @ ' + new Date().toLocaleTimeString()
    });

    if (failures > 0) {
        node.warn('Connectivity issue: DNS=' + JSON.stringify(dnsRes) + ' NET=' + JSON.stringify(inetRes) + ' LAN=' + JSON.stringify(lanRes));
    }

    const msgOk = { payload: ok };
    const msgDnsMs = dnsRes.ms != null ? { payload: dnsRes.ms } : null;
    const msgFails = { payload: failures };

    node.send([msgOk, msgDnsMs, msgFails]);
})();
return null;
